<script setup lang="ts">
import {Brush, CircleHelp, Crop, Eraser, Hand, Maximize, MousePointer2, PaintBucket, Pencil, Pipette, Scaling, Scan, Sparkles, ZoomIn} from 'lucide-vue-next';
import type {CanvasTool} from '../model/canvas-types';
const props=defineProps<{modelValue:CanvasTool;helpOpen:boolean}>(); const emit=defineEmits<{(e:'update:modelValue',value:CanvasTool):void;(e:'fit'):void;(e:'help'):void}>();
const tools=[
  {id:'move',label:'移动',shortcut:'V',description:'拖动图层位置，不显示缩放控制柄',icon:MousePointer2},{id:'transform',label:'变换',shortcut:'T',description:'移动图层或拖动八向控制柄调整大小',icon:Maximize},{id:'select',label:'矩形选区',shortcut:'M',description:'创建像素选区，用于复制或剪切',icon:Scan},{id:'crop',label:'裁剪',shortcut:'C',description:'调整八向裁剪框，按回车确认裁剪',icon:Crop},{id:'chroma',label:'色度抠图',shortcut:'K',description:'点击背景颜色并移除相连区域',icon:Sparkles},{id:'brush',label:'画笔',shortcut:'B',description:'使用柔边笔刷绘制颜色',icon:Brush},{id:'pencil',label:'铅笔',shortcut:'N',description:'使用单像素硬边笔触绘制',icon:Pencil},{id:'eraser',label:'橡皮擦',shortcut:'E',description:'擦除图层像素并生成透明区域',icon:Eraser},{id:'fill',label:'油漆桶',shortcut:'',description:'填充颜色相近的相邻区域',icon:PaintBucket},{id:'eyedropper',label:'吸管',shortcut:'I',description:'从当前图层拾取像素颜色',icon:Pipette},{id:'hand',label:'抓手',shortcut:'H',description:'拖动画布视图，不移动图层',icon:Hand},{id:'zoom',label:'缩放',shortcut:'',description:'点击放大，按 Shift 点击缩小',icon:ZoomIn}
] as const;
</script>
<template><nav class="canvas-toolbar" aria-label="画布工具"><button v-for="item in tools" :key="item.id" class="canvas-tool" :class="{'is-active':props.modelValue===item.id}" type="button" :aria-label="item.label+(item.shortcut?' ('+item.shortcut+')':'')" :aria-pressed="props.modelValue===item.id" @click="emit('update:modelValue',item.id)"><component :is="item.icon" :size="19" aria-hidden="true"/><span class="canvas-tool__tooltip" role="tooltip"><strong>{{item.label}}</strong><kbd v-if="item.shortcut">{{item.shortcut}}</kbd><small>{{item.description}}</small></span></button><span class="canvas-toolbar__divider"/><button class="canvas-tool" type="button" aria-label="适应内容" @click="emit('fit')"><Scaling :size="19" aria-hidden="true"/><span class="canvas-tool__tooltip" role="tooltip"><strong>适应内容</strong><kbd>Ctrl 0</kbd><small>缩放视图以显示完整画框</small></span></button><button class="canvas-tool canvas-toolbar__help" :class="{'is-active':props.helpOpen}" type="button" aria-label="快捷键帮助" :aria-expanded="props.helpOpen" @click="emit('help')"><CircleHelp :size="19" aria-hidden="true"/><span class="canvas-tool__tooltip" role="tooltip"><strong>快捷键帮助</strong><small>查看全部画布快捷键</small></span></button></nav></template>
